const j = items[0].json;
const m = j.meeting_data || {};
const html = `
${j.approved_content_html || ''}
<hr/>
<h2>Firmas</h2>
<p>Docente: ${j.teacher_signature ? 'Firmado' : 'Pendiente'}</p>
<p>Representante: ${j.representative_signature ? 'Firmado' : 'Pendiente'}</p>
<p>Fecha y hora de firma: ${j.signed_at || ''}</p>
`;
return [{ json: {
  meeting_id: j.meeting_id,
  final_document_html: html,
  teacher_name: m.teacher_name,
  student_name: m.student_name,
  representative_name: m.representative_name,
  meeting_date: m.date,
  status: 'final',
}}];
